import { Group, Mesh, PointLight, DirectionalLight, BoxGeometry, CircleGeometry, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { uv, vec2, smoothstep, distance, float } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'stat-tile-home';

  const cleanupFns = [];
  const timelines = [];

  // --- machined surface plaque -----------------------------------------
  const tileWidth = 1.8;
  const tileHeight = 1.05;
  const tileDepth = 0.14;

  // accent edge: slightly larger box set behind, revealing a thin accent border
  const edgeGeo = new BoxGeometry(tileWidth + 0.035, tileHeight + 0.035, tileDepth * 0.6);
  const edgeMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.accent),
    roughness: 0.45,
    metalness: 0.35,
    emissive: new Color(palette.accent),
    emissiveIntensity: 0.25,
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.035;
  group.add(edgeMesh);

  const plaqueGeo = new BoxGeometry(tileWidth, tileHeight, tileDepth);
  const plaqueMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });
  const plaque = new Mesh(plaqueGeo, plaqueMat);
  plaque.name = 'plaque';
  group.add(plaque);

  // surface backing panel to keep contrast against ink (surface color sliver)
  const backGeo = new BoxGeometry(tileWidth - 0.06, tileHeight - 0.06, tileDepth * 0.3);
  const backMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.surface),
    roughness: 0.6,
    metalness: 0.3,
  });
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.z = tileDepth * 0.5 + 0.02;
  group.add(backMesh);

  // --- contact shadow (radial falloff via TSL) ---------------------------
  const shadowRadius = tileWidth * 0.75;
  const shadowGeo = new CircleGeometry(shadowRadius, 48);
  const shadowUv = uv();
  const centered = shadowUv.sub(vec2(0.5, 0.5));
  const dist = distance(centered, vec2(0.0, 0.0));
  const falloff = smoothstep(float(0.5), float(0.05), dist);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
  });
  shadowMat.opacityNode = falloff.mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -tileHeight * 0.62, 0);
  group.add(shadowMesh);

  // --- node-local rim / accent lights ------------------------------------
  const rimLight = new PointLight(new Color(palette.accent), 0.8, 4.0, 2.0);
  rimLight.position.set(-0.8, 0.6, 0.9);
  group.add(rimLight);

  const backRim = new DirectionalLight(new Color(palette.paper), 0.6);
  backRim.position.set(0.6, 0.4, -1.2);
  group.add(backRim);

  // --- decorative machined gear mesh (from meshUrl) -----------------------
  let gearMesh = null;
  const meshUrl = config.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      gearMesh = gltf.scene;
      gearMesh.name = 'gear-accent';
      gearMesh.scale.setScalar(0.34);
      gearMesh.position.set(0, 0.02, tileDepth * 0.5 + 0.06);
      gearMesh.traverse((child) => {
        if (child.isMesh && child.material) {
          child.material.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
          child.material.metalness = Math.min(child.material.metalness ?? 0.5, 0.55);
        }
      });
      group.add(gearMesh);

      const spinTl = gsap.to(gearMesh.rotation, {
        z: `-=${Math.PI * 2}`,
        duration: 32,
        repeat: -1,
        ease: 'none',
      });
      timelines.push(spinTl);
    }).catch(() => {});
  }

  // --- text: only render what the spec actually supplies ------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let cursorY = 0.18;
  for (const item of items) {
    const role = item.role ?? 'body';
    const isValue = role.toLowerCase().includes('value') || role.toLowerCase().includes('stat');
    const fontSize = item.typography?.fontSize ?? (isValue ? 68 : 26);
    const txt = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize,
      color: isValue ? palette.paper : palette.accent,
      align: 'center',
      maxWidthPx: 420,
    });
    txt.position.set(0, cursorY, tileDepth * 0.5 + 0.05);
    cursorY -= isValue ? 0.42 : 0.24;
    group.add(txt);
    textNodes.push(txt);
  }

  // --- cinematic primitives (applied exactly as declared) ------------------
  const appliedPrimitives = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const result = fn(group, prim.params ?? {});
      appliedPrimitives.push(result);
    }
  }

  // --- interaction handlers -------------------------------------------------
  const baseY = group.position.y;
  let hoverTl = null;
  let pressTl = null;

  function onPointerEnter() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.to(group.position, { y: '+=0.15', duration: 0.6, ease: 'power2.out' }, 0);
    hoverTl.to(edgeMat, { emissiveIntensity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(group.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.5, ease: 'power2.out' }, 0);
  }

  function onPointerLeave() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    hoverTl.to(edgeMat, { emissiveIntensity: 0.25, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power2.out' }, 0);
  }

  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    timelines.push(pressTl);
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.35, ease: 'power4.out' });
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'stat-tile-home' });
  }

  group.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
    click: onClick,
  };

  // --- cleanup ----------------------------------------------------------
  group.userData.cleanup = () => {
    for (const tl of timelines) {
      if (tl && tl.kill) tl.kill();
    }
    for (const p of appliedPrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    edgeGeo.dispose();
    edgeMat.dispose();
    plaqueGeo.dispose();
    plaqueMat.dispose();
    backGeo.dispose();
    backMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    for (const t of textNodes) {
      t.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    }
    if (gearMesh) {
      gearMesh.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
          else child.material.dispose();
        }
      });
    }
  };

  return group;
}
